intentos.respuesta_cruda:
{
  "sql": "SELECT t.categoria_ingles, COALESCE(SUM(CASE WHEN p.payment_installments > 1 THEN 1 ELSE 0 END) * 100.0 / COUNT(DISTINCT p.order_id), 0) AS pct_pagos_plazos FROM ( SELECT DISTINCT CASE WHEN p.product_category_name IS NULL THEN 'sin_categoria' ELSE t.product_category_name_english END AS categoria_ingles, o.order_id FROM order_items oi JOIN products p ON oi.product_id = p.product_id LEFT JOIN product_category_translation t ON t.product_category_name = p.product_category_name JOIN order_payments p ON oi.order_id = p.order_id JOIN vw_pedidos_validos o ON oi.order_id = o.order_id WHERE p.payment_type != 'not_defined' ) t GROUP BY t.categoria_ingles HAVING COUNT(DISTINCT t.order_id) >= 100 ORDER BY t.categoria_ingles LIMIT 1"
}
